#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int maxProduct(char **words, int wordsSize) {
    int *masks = (int *)calloc((size_t)wordsSize, sizeof(int));
    if (!masks) return 0;
    for (int i = 0; i < wordsSize; ++i) {
        for (const char *p = words[i]; *p; ++p) masks[i] |= 1 << (*p - 'a');
    }
    int best = 0;
    for (int i = 0; i < wordsSize; ++i) {
        for (int j = i + 1; j < wordsSize; ++j) {
            if ((masks[i] & masks[j]) == 0) {
                int product = (int)strlen(words[i]) * (int)strlen(words[j]);
                if (product > best) best = product;
            }
        }
    }
    free(masks);
    return best;
}

static int parse_words(const char *line, char ***out) {
    const char *p = strstr(line, "[[");
    if (!p) return 0; p += 2;
    int cap = 16, n = 0;
    char **words = malloc((size_t)cap * sizeof(char*));
    while (*p && *p != ']') {
        while (*p && *p != '"' && *p != ']') ++p;
        if (*p == ']') break; ++p;
        const char *s = p; while (*p && *p != '"') ++p;
        if (!*p) break; size_t len = (size_t)(p - s);
        char *w = malloc(len + 1); memcpy(w, s, len); w[len] = '\0';
        if (n == cap) { cap *= 2; words = realloc(words, (size_t)cap * sizeof(char*)); }
        words[n++] = w; ++p;
    }
    *out = words; return n;
}

