class Solution {
    public int maxProduct(String[] words) {
        int n = words.length;
        int[] masks = new int[n];
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = 0; j < words[i].length(); j++) mask |= 1 << (words[i].charAt(j) - 'a');
            masks[i] = mask;
        }
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if ((masks[i] & masks[j]) == 0) best = Math.max(best, words[i].length() * words[j].length());
            }
        }
        return best;
    }
}

